import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"38、【睽】 兑下离上","description":"周易尚氏学 - 38、【睽】 兑下离上","frontmatter":{"title":"38、【睽】 兑下离上","description":"周易尚氏学 - 38、【睽】 兑下离上"},"headers":[],"relativePath":"zh/classics/shangshi/043.md","filePath":"zh/classics/shangshi/043.md"}'),s={name:"zh/classics/shangshi/043.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_38、【睽】-兑下离上" tabindex="-1">38、【睽】 兑下离上 <a class="header-anchor" href="#_38、【睽】-兑下离上" aria-label="Permalink to “38、【睽】 兑下离上”">​</a></h1><p>归藏作瞿。说文鹰隼视也。礼玉藻视容瞿瞿。注惊视不审貌。夫惊而惧。视而不审。则视象必至乖违明矣。至周易日睽。义与瞿略同。睽乖也。说文目不相听也。卦三至五两目相背。相背则视乖。听从也。不相从。则一目视为彼。一目视为此。如三上所言是也。盖卦之得名。全以卦象。六书故。睽反目也。与说文义同。自反目之义失。旧解于三上爻辞皆莫详其故矣。小谓阴。六五得中有应。故小事吉也。</p><p>彖曰。睽。火动而上。泽动而下。二女同居。其志不同行。说而丽乎明。柔进而上行。得中而应乎刚。是以小事吉。天地睽而其事同也。男女睽而其志通也。万物睽而其事类也。睽之时用大矣哉。</p><p>火性炎上而即居上。水润下而即居下。愈去愈远。故二女同居不同行。坎为志也。然所以睽者。以同为女也。若夫天地男女。其形虽睽隔。而其功用。无不和合而同也。其心志无不相感而通也。即推而至于万物。若繁赜不可计数矣。然只有物即有阴阳。有牝牡。阴阳牝牡。则必合而为类无疑也。故睽亦有时有用也。</p><p>象曰。上火下泽。睽。君子以同而异。</p><p>同者同为女。异者不同行。君子法之。不拘于一。</p><p>初九。悔亡，丧马。勿逐自复。见恶人。无咎。</p><p>震为马。兑二折震。震毁。故曰丧马。震为复。二必升五。升五则下成震。故曰自复。离为恶人。初前遇之。兑见。故曰见恶人。盖初居潜龙之位。勿用之时。居易俟命。无所动作。故悔亡而无咎也。</p><h3 id="象曰。见恶人。以辟咎也。" tabindex="-1">象曰。见恶人。以辟咎也。 <a class="header-anchor" href="#象曰。见恶人。以辟咎也。" aria-label="Permalink to “象曰。见恶人。以辟咎也。”">​</a></h3><p>九二。遇主于巷。无咎。</p><p>五为卦主。丰九四云。遇其夷主是也。二应之。离为巷。故曰遇主于巷。有应得中。故无咎。离巷象失传。易林无妄之小畜云。鱿虾去海。游于枯里。街道迫狭。不得自在。小畜上巽为鱼。故曰鱿虾。乾为海。巽在外。故曰去海。离为桔为里为街巷。说文巷里道。诗郑风巷无居人。传曰巷里涂。离上下阳。中虚。俨然里巷也。巷为里道。故象曰未失道。巷象失传。故旧解无不误。不足怪也。</p><h3 id="象曰。遇主于巷。未失道也。" tabindex="-1">象曰。遇主于巷。未失道也。 <a class="header-anchor" href="#象曰。遇主于巷。未失道也。" aria-label="Permalink to “象曰。遇主于巷。未失道也。”">​</a></h3><p>得应。故曰未失道。</p><p>六三。见舆曳。其牛掣。其人天且劓。无初有终。</p><p>兑为见。坎为舆。为曳。坎舆在前。而三居坎后。故曰见舆曳。五离为牛。掣郑作。云牛角皆踊也。踊起也。说文作奖。云角一仰一俯。子夏传作奖。云一角仰。案契契（下加解）同字。皆音挚。义皆同。又易林大言之睽云。伤破妄行。触壁契（下加解）墙。亦以角踊为说。不以滞隔为训。只王弼作掣。音与诸家同。义与诸家异。非也。其牛契（？）者言牛角腾踊上出也。天。马融云契（？）凿其额曰天。虞翻云黥额为天。割鼻为劓。鲸即古之墨刑。马云凿殆误也。艮为额为鼻。艮伏不见。故曰劓。兑上毁缺。故曰天。惟古刑无名天者。俞越（左　）云。天为兀字。古文天作兀（下再加兀）。以形近。故兀讹为天。庄子云。鲁有兀者。释文云。刖足曰兀。其人兀且劓。犹困九五曰劓刖也。按三震象半见。故曰刖足。俞氏之说或是也。又胡安定云。天当作而。古文相类。传写遂误。在汉法脸罪。无髡其鬓发日而。又周礼梓人。作其鳞之而。亦谓髡其鬓发。按之而。注训为颊版。释文云秃也。玉篇亦训颀为秃。贾疏亦无髡其鬓发之解。然版之为秃。字书皆同。则而者秃也。秃则天然无发。不必受刑。似胡说不如俞说优也。三不当位。故初不吉。有应承阳。故曰有终。</p><h3 id="象曰。见奥曳。位不当也。无初有终。遇刚也。" tabindex="-1">象曰。见奥曳。位不当也。无初有终。遇刚也。 <a class="header-anchor" href="#象曰。见奥曳。位不当也。无初有终。遇刚也。" aria-label="Permalink to “象曰。见奥曳。位不当也。无初有终。遇刚也。”">​</a></h3><p>位不当故无初。遇刚故有终。</p><p>九四。睽孤。遇元夫。交孚。厉无咎。</p><p>坎为孤为夫。虞翻强令四变成震。以取夫象。岂知左传襄二十四年。筮遇困之大过。坎变巽。曰夫从风。以坎为夫也。坎者乾元之精。故曰元夫。比曰元永贞。是其义也。四上下皆阴。故曰交孚。坎险故曰厉。交孚则志行。故厉无咎。</p><h3 id="象曰。交孚无咎。志行也。" tabindex="-1">象曰。交孚无咎。志行也。 <a class="header-anchor" href="#象曰。交孚无咎。志行也。" aria-label="Permalink to “象曰。交孚无咎。志行也。”">​</a></h3><p>坎为志。志行。言阳得阴则孚也。此爻旧解。皆用虞氏交变。取夫象。信汉儒不信左氏。岂不异哉。</p><p>六五。悔亡。厥宗噬肤。往何咎。</p><p>同人六二云。同人于宗。以五阳为宗。宗主也。坤先述后得主是也。兹以九二为宗。艮为肤。以刚在外也。故离亦为肤。二兑体。兑口逼近离肤。故曰厥宗噬肤。然二为正应。二五相上下。各得位。故往无咎。离肤象。易林师之井云。范子妙材。戮辱伤肤。井互离。兑毁折。故曰戮辱。离兑连体。故伤肤。是焦氏以离为肤也。井中爻亦睽也。</p><h3 id="象曰。厥宗噬肤。往有庆也。" tabindex="-1">象曰。厥宗噬肤。往有庆也。 <a class="header-anchor" href="#象曰。厥宗噬肤。往有庆也。" aria-label="Permalink to “象曰。厥宗噬肤。往有庆也。”">​</a></h3><p>得阳应。故曰有庆。</p><p>上九。膜孤。见豕负涂。载鬼一车。先张之弧。后说之壶。匪寇。婚媾。往遇雨则吉。</p><p>睽为反目。目反故所见不同。一日见为豕。一见为鬼。一目见张弧而惧。一见说壶而喜。一见为寇。一见为婚媾也。见字统全爻而言。反目之精神全出。旧解若只见豕负涂者。由不知睽之取象。在反目也。离为见。互坎为豕。为涂。为车。为鬼。坎数一。故曰一车。坎为弧为矢。张弧则欲射我矣。离为壶。说遗也。而坎为酒。遗我以壶酒、则意善也。坎为寇。三虽坎体。而应上九。则婚媾也。寇则非矣。兑为雨。上往居三。故曰遇雨。三上相上下。各当位。故吉。之上内。宜曰来。然赛五往外也。曰朋来。需三往上也。曰三人来。盖自本位言则曰来。去本位言则曰往。不能执也。壶。王弼作弧。兹从京马郑王肃翟子玄。说。释文始锐反。音税。</p><h3 id="象曰。遇雨之吉。君疑亡也。" tabindex="-1">象曰。遇雨之吉。君疑亡也。 <a class="header-anchor" href="#象曰。遇雨之吉。君疑亡也。" aria-label="Permalink to “象曰。遇雨之吉。君疑亡也。”">​</a></h3><p>坎为疑。疑之故全在坎。上往三成大壮。天雷一震。坎象消释。故曰群疑亡。坎为众。故曰群疑。即上所见诸象也。</p>',29)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
